import { z } from 'zod';

import { IsoDateTime, Uuid } from './common';
import { defineRoute } from './define-route';

// Contracts of the daily warm-up (SPEC-714 ET-1, EF-7, BR-AUT-03). The activity is created by the
// `echauffement` automation before the next session of the day; the home screen reads it with one
// call and records the first pass answer by answer. A notion « À revoir » joins the global quiz of
// the evening; nothing here is generated by AI at read time.

/** EF-2 — the scheduled sessions an echauffement can precede. */
export const WARMUP_SESSION_KINDS = [
  'course',
  'exercise',
  'validation_quiz',
  'contributions',
  'mock_exam',
] as const;
export const WarmupSessionKind = z.enum(WARMUP_SESSION_KINDS);
export type WarmupSessionKind = z.infer<typeof WarmupSessionKind>;

/** EF-3 — why a notion belongs to the selection (SPEC-410 reasons). */
export const WARMUP_TAGS = ['yesterday', 'prerequisite'] as const;
export const WarmupTag = z.enum(WARMUP_TAGS);
export type WarmupTag = z.infer<typeof WarmupTag>;

/** EF-7 — the session the warm-up is placed before. `startsAt` keeps the learner's offset. */
export const WarmupNextSession = z.object({
  kind: WarmupSessionKind,
  startsAt: IsoDateTime,
  href: z.string().min(1),
});
export type WarmupNextSession = z.infer<typeof WarmupNextSession>;

/** EF-7 — one question with its origin badge and the reference module of a prerequisite. */
export const WarmupItem = z.object({
  position: z.number().int().min(0),
  notionId: Uuid,
  notionLabel: z.string().min(1).max(120),
  tag: WarmupTag,
  moduleNumber: z.number().int().min(1).nullable(),
  question: z.string().min(1).max(2000),
  answer: z.string().min(1).max(4000),
});
export type WarmupItem = z.infer<typeof WarmupItem>;

/** EF-8 — a recorded first-pass answer: « Je savais » (true) or « À revoir » (false). */
export const WarmupAnswer = z.object({
  position: z.number().int().min(0),
  knew: z.boolean(),
});
export type WarmupAnswer = z.infer<typeof WarmupAnswer>;

export const WARMUP_STATUSES = ['todo', 'in_progress', 'done'] as const;
export const WarmupStatus = z.enum(WARMUP_STATUSES);
export type WarmupStatus = z.infer<typeof WarmupStatus>;

/** EF-7 — one formation's warm-up of the day, as displayed by the home card. */
export const WarmupDto = z.object({
  activityId: Uuid,
  formationId: Uuid,
  nextSession: WarmupNextSession,
  scope: z.enum(['yesterday_prerequisites', 'yesterday']),
  items: z.array(WarmupItem),
  answers: z.array(WarmupAnswer),
  status: WarmupStatus,
  /** CL-8 — true when the evening quiz already started: « prochain quiz global » in the card. */
  reviewRemaining: z.boolean().optional(),
});
export type WarmupDto = z.infer<typeof WarmupDto>;

/** EF-7 — one entry per formation, sorted by the next session hour. */
export const WarmupTodayDto = z.object({
  items: z.array(WarmupDto),
});
export type WarmupTodayDto = z.infer<typeof WarmupTodayDto>;

/** ET-2 — first-pass answer; `position` is the 0-based item position of the DTO. */
export const WarmupAnswerBody = z.object({
  position: z.number().int().min(0),
  knew: z.boolean(),
});
export type WarmupAnswerBody = z.infer<typeof WarmupAnswerBody>;

export const WarmupAnswerParams = z.object({ activityId: Uuid });
export type WarmupAnswerParams = z.infer<typeof WarmupAnswerParams>;

/** ET-2 — the warm-ups of the connected learner, one entry per formation. */
export const warmupTodayGet = defineRoute({
  id: 'warmups.today.get',
  method: 'GET',
  path: '/api/v1/warmups/today',
  auth: 'user',
  output: WarmupTodayDto,
  successStatus: 200,
  summary:
    'Lit les échauffements du jour du seul utilisateur connecté, une entrée par formation, triés par heure de séance (SPEC-714).',
  errors: ['UNAUTHENTICATED', 'NOT_FOUND', 'INTERNAL_ERROR'],
});

/** ET-2 — records the first-pass answer of one question; a repeated position is a 409. */
export const warmupAnswer = defineRoute({
  id: 'warmups.answers.create',
  method: 'POST',
  path: '/api/v1/warmups/:activityId/answers',
  auth: 'user',
  params: WarmupAnswerParams,
  body: WarmupAnswerBody,
  output: WarmupDto,
  successStatus: 200,
  idempotent: true,
  summary:
    'Enregistre « Je savais » ou « À revoir » sur une question d’échauffement, applique FSRS et ajoute la notion au quiz global du soir (SPEC-714).',
  errors: [
    'VALIDATION_FAILED',
    'NOT_FOUND',
    'CONFLICT',
    'UNAUTHENTICATED',
    'IDEMPOTENCY_KEY_REQUIRED',
    'IDEMPOTENCY_IN_PROGRESS',
    'INTERNAL_ERROR',
  ],
});

export const warmupRoutes = {
  warmupTodayGet,
  warmupAnswer,
} as const;
